import React from 'react';
import './Skills.css';
const Skills = () => {
    return (
        <div>
            <h2>LANGUAGES I SPEAK</h2>
            <div className="logo-container">
                <img src="/img/frame.png" alt="HTML" />
                <img src="/img/mysql_svgrepo.com.png" alt="MySQL" />
                <img src="python_svgrepo.com.png" alt="Python" />
                <img src="django_svgrepo.com.png" alt="Django" />
            </div>
            <div className="logo-container">
                <img src="react_1_logo_svgrepo.com.png" alt="React" />
                <img src="laravel_svgrepo.com.png" alt="Laravel" />
            </div>
        </div>
    );
};

export default Skills;
